// d[i]: a[i]로 끝나는 가장 긴 증가하는 부분 수열의 길이
int ans = 0;
for (int i = 0; i < n; i++) {
    d[i] = 1;
    for (int j = 0; j < i; j++)
        if (a[j] < a[i]) d[i] = max(d[i], d[j] + 1);
    ans = max(ans, d[i]);
}

